def backup_phone(device):
    import os
    from shutil import copytree, ignore_patterns

    path = f"C:/Backups/{device}"

    if not os.path.exists(path):
        os.makedirs(path)

    try:
        copytree(f"C:/Users/Username/PhoneData", path, ignore=ignore_patterns('*.tmp', '*.log'))
    except Exception as e:
        print(e)

backup_phone("Samsung")

